INSERT OR IGNORE INTO "Startup" ("id", "slug", "name", "field", "stage", "status", "summary", "solution", "founder", "website", "featured", "displayOrder", "createdAt", "updatedAt") VALUES
('seed_startup_aftab', 'aftab', 'مرکز نوآوری آفتاب', 'فناوری فرهنگی', 'growth', 'published', 'تیمی مسئله‌محور برای توسعه راهکارهای نوآورانه در بازار صنایع خلاق ایران.', 'تمرکز تیم بر ساخت و اعتبارسنجی راهکارهای قابل استفاده برای فعالان صنایع فرهنگی و خلاق است.', 'علی رضایی', 'https://example.ir', 1, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('seed_startup_local_market', 'local-market', 'راهکار بازار محلی', 'تجارت اجتماعی', 'prototype', 'published', 'راهکاری برای پیوند کسب‌وکارهای محلی با بازار و مشتریان جدید.', 'محصول با ساده‌سازی معرفی، سفارش و ارتباط با مشتری به فروشندگان محلی کمک می‌کند.', 'سارا محمدی', NULL, 1, 2, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('seed_startup_sepehr', 'sepehr', 'استودیو سپهر', 'محتوای دیجیتال', 'growth', 'published', 'استودیویی خلاق برای تولید تجربه‌ها و محتوای دیجیتال مسئله‌محور.', 'تیم روی طراحی و تولید محتوای تعاملی با قابلیت توسعه برای بازارهای مختلف کار می‌کند.', 'محمد کریمی', NULL, 1, 3, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('seed_startup_rahkar', 'rahkar', 'راهکار نوآفرین', 'طراحی و محصول', 'validation', 'published', 'تیمی برای طراحی محصولات ساده و قابل سنجش بر پایه نیاز واقعی کاربران.', 'نسخه اولیه محصول ساخته شده و تیم در حال آزمون و اصلاح آن با بازخورد کاربران است.', 'نرگس موسوی', NULL, 1, 4, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('seed_startup_mana', 'mana', 'زیست‌بوم مانا', 'صنایع خلاق', 'validation', 'draft', 'پروفایل این تیم هنوز در حال تکمیل است.', NULL, NULL, NULL, 0, 5, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('seed_startup_boom', 'boom', 'نوآوران بوم', 'طراحی و محصول', 'idea', 'review', 'این تیم در مرحله بازبینی اطلاعات و مسیر محصول قرار دارد.', NULL, NULL, NULL, 0, 6, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);

INSERT OR IGNORE INTO "News" ("id", "slug", "title", "summary", "body", "tags", "category", "status", "publishedAt", "featured", "views", "createdAt", "updatedAt") VALUES
('seed_news_gathering', 'selected-teams-gathering', 'نخستین گردهمایی تیم‌های منتخب خانه خلاق آینه برگزار شد', 'تیم‌های منتخب در یک نشست مشترک مسیر توسعه محصول، شبکه منتورینگ و برنامه‌های ماه‌های پیش‌رو را مرور کردند.', 'نخستین گردهمایی تیم‌های منتخب خانه خلاق آینه با هدف آشنایی تیم‌ها، مرور مسئله‌های اصلی و طراحی مسیر رشد برگزار شد. در این نشست، هر تیم وضعیت فعلی محصول و بازار خود را ارائه کرد و بازخورد اولیه منتورها را دریافت کرد.\n\nدر ادامه، برنامه جلسات تخصصی، نقاط ارزیابی و خروجی‌های کوتاه‌مدت هر تیم مشخص شد تا فرآیند همراهی با تمرکز بیشتر ادامه پیدا کند.', 'خانه خلاق، استارتاپ، منتورینگ', 'activity-report', 'published', '2026-09-01T09:00:00+03:30', 1, 328, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('seed_news_mentoring', 'teams-enter-mentoring', 'سه تیم خلاق وارد مرحله منتورینگ و توسعه محصول شدند', 'سه تیم پس از ارزیابی اولیه وارد مرحله منتورینگ تخصصی و توسعه محصول شدند.', 'پس از بررسی وضعیت تیم‌ها و نیازهای اصلی محصول، سه تیم منتخب وارد مرحله منتورینگ شدند. جلسات این مرحله بر اعتبارسنجی مسئله، طراحی محصول و برنامه ورود به بازار تمرکز دارد.', 'استارتاپ، منتورینگ', 'news', 'published', '2026-08-18T09:00:00+03:30', 0, 241, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('seed_news_workshop', 'problem-workshop-day', 'یک روز از کارگاه مسئله‌محور خانه خلاق؛ از ایده تا نمونه اولیه', 'روایتی کوتاه از یک روز کارگاه مسئله‌محور با تمرکز بر تعریف مسئله و ساخت نمونه اولیه.', 'در این کارگاه تیم‌ها مسئله‌های خود را بازتعریف کردند، فرضیه‌های اصلی را نوشتند و برای ساخت یک نمونه قابل آزمون برنامه‌ریزی کردند.', 'کارگاه، مسئله، محصول', 'activity-report', 'draft', NULL, 0, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('seed_news_growth_call', 'growth-program-call', 'فراخوان دوره جدید برنامه رشد و شتابدهی منتشر شد', 'ثبت‌نام دوره جدید برنامه رشد برای تیم‌های خلاق و مسئله‌محور آغاز شد.', 'خانه خلاق آینه از تیم‌هایی که روی یک مسئله واقعی کار می‌کنند دعوت می‌کند در دوره جدید برنامه رشد ثبت‌نام کنند. جزئیات فرآیند ارزیابی و زمان‌بندی از طریق صفحه برنامه‌ها اعلام می‌شود.', 'فراخوان، رشد', 'call', 'published', '2026-06-12T09:00:00+03:30', 0, 184, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('seed_news_market_session', 'problem-to-market-session', 'نشست تجربه‌محور «از مسئله تا بازار» در خانه خلاق برگزار شد', 'در این نشست تجربه‌های عملی درباره شناخت مسئله، ساخت محصول و ورود به بازار مرور شد.', 'منتورها و تیم‌های حاضر درباره فاصله میان ایده و بازار، روش‌های آزمون فرضیه و تصمیم‌گیری بر اساس بازخورد کاربر گفت‌وگو کردند.', 'نشست، بازار', 'report', 'published', '2026-05-20T09:00:00+03:30', 0, 122, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('seed_news_mentor_network', 'mentor-network', 'خانه خلاق آینه میزبان شبکه‌ای از منتورها و متخصصان شد', 'شبکه همراهان تخصصی خانه خلاق برای پشتیبانی از تیم‌ها توسعه پیدا کرد.', 'متخصصان حوزه محصول، بازار، طراحی و کسب‌وکار در قالب شبکه منتورینگ در کنار تیم‌های خانه خلاق قرار می‌گیرند تا تصمیم‌های کلیدی مسیر رشد با کیفیت بیشتری گرفته شود.', 'منتور، همراهان', 'collaboration', 'published', '2026-04-16T09:00:00+03:30', 0, 96, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('seed_news_autumn_call', 'autumn-growth-call', 'آغاز فراخوان برنامه رشد پاییز', 'فراخوان برنامه رشد پاییز برای تیم‌های واجد شرایط زمان‌بندی شده است.', 'اطلاعات تکمیلی فراخوان پس از نهایی شدن برنامه منتشر خواهد شد.', 'فراخوان', 'call', 'scheduled', '2026-10-01T09:00:00+03:30', 0, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('seed_news_partner', 'new-partner', 'همراه جدید خانه خلاق معرفی شد', 'اطلاعات این خبر در حال بازبینی است.', 'متن خبر پس از تکمیل اطلاعات همکاری منتشر خواهد شد.', 'همکاری', 'collaboration', 'review', NULL, 0, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
